import{_ as p,a0 as l,w as o,s as d,I as t,x as e,a1 as a,A as i,ao as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const m=JSON.parse('{"title":"使用 Docker 企業版搭建自己的私有註冊服務器 | LCTT x X-CMD","titleTemplate":false,"description":"使用 Docker 企業版搭建自己的私有註冊服務器 | LCTT (201811) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用 Docker 企業版搭建自己的私有註冊服務器 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用 Docker 企業版搭建自己的私有註冊服務器 | LCTT (201811) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201811/20180110 Using Your Own Private Registry with Docker Enterprise Edition","title":"使用 Docker 企業版搭建自己的私有註冊服務器","tag":"201811","desc":""},"relativePath":"201811/20180110 Using Your Own Private Registry with Docker Enterprise Edition.md","filePath":"[post].md"}'),k={name:"201811/20180110 Using Your Own Private Registry with Docker Enterprise Edition.md"};function u(g,s,c,T,D,h){const n=l("Link");return o(),d("div",null,[s[26]||(s[26]=t("h1",{id:"使用-docker-企業版搭建自己的私有註冊服務器",tabindex:"-1"},[e("使用 Docker 企業版搭建自己的私有註冊服務器 "),t("a",{class:"header-anchor",href:"#使用-docker-企業版搭建自己的私有註冊服務器","aria-label":"Permalink to “使用 Docker 企業版搭建自己的私有註冊服務器”"},"​")],-1)),s[27]||(s[27]=t("p",null,[t("img",{src:"https://i1.wp.com/blog.docker.com/wp-content/uploads/ccd278d2-29c2-4866-8285-c2fe60b4bd5e-1.jpg?resize=965%2C452&ssl=1",alt:"docker trusted registry"})],-1)),t("p",null,[s[1]||(s[1]=e("Docker 真的很酷，特別是和使用虛擬機相比，轉移 Docker 鏡像十分容易。如果你已準備好使用 Docker，那你肯定已從 ",-1)),a(n,{href:"https://hub.docker.com/"},{default:i(()=>[...s[0]||(s[0]=[e("Docker Hub",-1)])]),_:1}),s[2]||(s[2]=e(" 上拉取過完整的鏡像。Docker Hub 是 Docker 的雲端註冊服務器服務，它包含成千上萬個供選擇的 Docker 鏡像。如果你開發了自己的軟件包並創建了自己的 Docker 鏡像，那麼你會想有自己私有的註冊服務器。如果你有搭配着專有許可的鏡像，或想為你的構建系統提供複雜的持續集成（CI）過程，則更應該擁有自己的私有註冊服務器。",-1))]),t("p",null,[s[5]||(s[5]=e("Docker 企業版包括 ",-1)),s[6]||(s[6]=t("ruby",null,[e("Docker 可信註冊服務器"),t("rt",null,"Docker Trusted Registry")],-1)),s[7]||(s[7]=e("（DTR）。這是一個具有安全鏡像管理功能的高可用的註冊服務器，為在你自己的數據中心或基於雲端的架構上運行而構建。在接下來，我們將瞭解到 DTR 是提供安全、可重用且連續的",-1)),a(n,{href:"https://blog.docker.com/2016/08/securing-enterprise-software-supply-chain-using-docker/"},{default:i(()=>[...s[3]||(s[3]=[e("軟件供應鏈",-1)])]),_:1}),s[8]||(s[8]=e("的一個關鍵組件。你可以通過我們的",-1)),a(n,{href:"https://www.docker.com/trial"},{default:i(()=>[...s[4]||(s[4]=[e("免費託管小樣",-1)])]),_:1}),s[9]||(s[9]=e("立即開始使用，或者通過下載安裝進行 30 天的免費試用。下面是開始自己安裝的步驟。",-1))]),s[28]||(s[28]=r(`<h3 id="配置-docker-企業版" tabindex="-1">配置 Docker 企業版 <a class="header-anchor" href="#配置-docker-企業版" aria-label="Permalink to “配置 Docker 企業版”">​</a></h3><p>DTR 運行於通用控制面板（UCP）之上，所以開始前要安裝一個單節點集羣。如果你已經有了自己的 UCP 集羣，可以跳過這一步。在你的 docker 託管主機上，運行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 拉取並安裝 UCP</span></span>
<span class="line"><span>docker run -it -rm -v /var/run/docker.sock:/var/run/docker.sock -name ucp docker/ucp:latest install</span></span></code></pre></div>`,3)),t("p",null,[s[11]||(s[11]=e("當 UCP 啓動並運行後，在安裝 DTR 之前你還有幾件事要做。針對剛剛安裝的 UCP 實例，打開瀏覽器。在日誌輸出的末尾應該有一個鏈接。如果你已經有了 Docker 企業版的許可證，那就在這個界面上輸入它吧。如果你還沒有，可以訪問 ",-1)),a(n,{href:"https://store.docker.com/search?offering=enterprise&page=1&q=&type=edition"},{default:i(()=>[...s[10]||(s[10]=[e("Docker 商店",-1)])]),_:1}),s[12]||(s[12]=e("獲取 30 天的免費試用版。",-1))]),s[29]||(s[29]=r(`<p>準備好許可證後，你可能會需要改變一下 UCP 運行的端口。因為這是一個單節點集羣，DTR 和 UCP 可能會以相同的端口運行它們的 web 服務。如果你擁有不只一個節點的 UCP 集羣，這就不是問題，因為 DTR 會尋找有所需空閒端口的節點。在 UCP 中，點擊“管理員設置 -&gt; 集羣配置”並修改控制器端口，比如 5443。</p><h3 id="安裝-dtr" tabindex="-1">安裝 DTR <a class="header-anchor" href="#安裝-dtr" aria-label="Permalink to “安裝 DTR”">​</a></h3><p>我們要安裝一個簡單的、單節點的 DTR 實例。如果你要安裝實際生產用途的 DTR，那麼你會將其設置為高可用（HA）模式，即需要另一種存儲介質，比如基於雲端的對象存儲或者 NFS（LCTT 譯註：Network File System，網絡文件系統）。因為目前安裝的是一個單節點實例，我們依然使用默認的本地存儲。</p><p>首先我們需要拉取 DTR 的 bootstrap 鏡像。boostrap 鏡像是一個微小的獨立安裝程序，包括了連接到 UCP 以及設置和啓動 DTR 所需的所有容器、卷和邏輯網絡。</p><p>使用命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 拉取並運行 DTR 引導程序</span></span>
<span class="line"><span>docker run -it -rm docker/dtr:latest install -ucp-insecure-tls</span></span></code></pre></div><p>注意：默認情況下，UCP 和 DTR 都有自己的證書，系統無法識別。如果你已使用系統信任的 TLS 證書設置 UCP，則可以省略 <code>-ucp-insecure-tls</code> 選項。另外，你可以使用 <code>-ucp-ca</code> 選項來直接指定 UCP 的 CA 證書。</p><p>然後 DTR bootstrap 鏡像會讓你確定幾項設置，比如 UCP 安裝的 URL 地址以及管理員的用户名和密碼。從拉取所有的 DTR 鏡像到設置全部完成，只需要一到兩分鐘的時間。</p><h3 id="保證一切安全" tabindex="-1">保證一切安全 <a class="header-anchor" href="#保證一切安全" aria-label="Permalink to “保證一切安全”">​</a></h3><p>一切都準備好後，就可以向註冊服務器推送或者從中拉取鏡像了。在做這一步之前，讓我們設置 TLS 證書，以便與 DTR 安全地通信。</p><p>在 Linux 上，我們可以使用以下命令（只需確保更改了 <code>DTR_HOSTNAME</code> 變量，來正確映射我們剛剛設置的 DTR）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 從 DTR 拉取 CA 證書（如果 curl 不可用，你可以使用 wget）</span></span>
<span class="line"><span>DTR_HOSTNAME=&lt; DTR 主機名&gt;</span></span>
<span class="line"><span>curl -k https://$(DTR_HOSTNAME)/ca &gt; $(DTR_HOSTNAME).crt</span></span>
<span class="line"><span>sudo mkdir /etc/docker/certs.d/$(DTR_HOSTNAME)</span></span>
<span class="line"><span>sudo cp $(DTR_HOSTNAME) /etc/docker/certs.d/$(DTR_HOSTNAME)</span></span>
<span class="line"><span># 重啓 docker 守護進程（在 Ubuntu 14.04 上，使用 \`sudo service docker restart\` 命令）</span></span>
<span class="line"><span>sudo systemctl restart docker</span></span></code></pre></div><p>對於 Mac 和 Windows 版的 Docker，我們會以不同的方式安裝客户端。轉入“設置 -&gt; 守護進程”，在“不安全的註冊服務器”部分，輸入你的 DTR 主機名。點擊“應用”，docker 守護進程應在重啓後可以良好使用。</p><h3 id="推送和拉取鏡像" tabindex="-1">推送和拉取鏡像 <a class="header-anchor" href="#推送和拉取鏡像" aria-label="Permalink to “推送和拉取鏡像”">​</a></h3><p>現在我們需要設置一個倉庫來存放鏡像。這和 Docker Hub 有一點不同，如果你做的 docker 推送倉庫中不存在，它會自動創建一個。要創建一個倉庫，在瀏覽器中打開 <code>https://&lt;Your DTR hostname&gt;</code> 並在出現登錄提示時使用你的管理員憑據登錄。如果你向 UCP 添加了許可證，則 DTR 會自動獲取該許可證。如果沒有，請現在確認上傳你的許可證。</p><p>進入剛才的網頁之後，點擊“新建倉庫”按鈕來創建新的倉庫。</p><p>我們會創建一個用於存儲 Alpine linux 的倉庫，所以在名字輸入處鍵入 “alpine”，點擊“保存”（在 DTR 2.5 及更高版本中叫“創建”）。</p><p>現在我們回到 shell 界面輸入以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 拉取 Alpine Linux 的最新版</span></span>
<span class="line"><span>docker pull alpine:latest</span></span>
<span class="line"><span># 登入新的 DTR 實例</span></span>
<span class="line"><span>docker login &lt;Your DTR hostname&gt;</span></span>
<span class="line"><span># 標記上 Alpine 使能推送其至你的 DTR</span></span>
<span class="line"><span>docker tag alpine:latest &lt;Your DTR hostname&gt;/admin/alpine:latest</span></span>
<span class="line"><span># 向 DTR 推送鏡像</span></span>
<span class="line"><span>docker push &lt;Your DTR hostname&gt;/admin/alpine:latest</span></span></code></pre></div><p>就是這樣！我們剛剛推送了最新的 Alpine Linux 的一份拷貝，重新打了標籤以便將其存儲到 DTR 中，並將其推送到我們的私有註冊服務器。如果你想將鏡像拉取至不同的 Docker 引擎中，按如上所示設置你的 DTR 證書，然後執行以下命令：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># 從 DTR 中拉取鏡像</span></span>
<span class="line"><span>docker pull &lt;Your DTR hostname&gt;/admin/alpine:latest</span></span></code></pre></div><p>DTR 具有許多優秀的鏡像管理功能，例如鏡像的緩存、映像、掃描、簽名甚至自動化供應鏈策略。這些功能我們在後期的Blog文章中更詳細的探討。</p><hr>`,23)),t("p",null,[s[14]||(s[14]=e("via: ",-1)),a(n,{href:"https://blog.docker.com/2018/01/dtr/"},{default:i(()=>[...s[13]||(s[13]=[e("https://blog.docker.com/2018/01/dtr/",-1)])]),_:1})]),t("p",null,[s[18]||(s[18]=e("作者：",-1)),a(n,{href:"https://blog.docker.com/author/pdevine/"},{default:i(()=>[...s[15]||(s[15]=[e("Patrick Devine",-1)])]),_:1}),s[19]||(s[19]=e(" 譯者：",-1)),a(n,{href:"https://github.com/fuowang"},{default:i(()=>[...s[16]||(s[16]=[e("fuowang",-1)])]),_:1}),s[20]||(s[20]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[17]||(s[17]=[e("wxy",-1)])]),_:1})]),t("p",null,[s[23]||(s[23]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[21]||(s[21]=[e("LCTT",-1)])]),_:1}),s[24]||(s[24]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[22]||(s[22]=[e("Linux中國",-1)])]),_:1}),s[25]||(s[25]=e(" 榮譽推出",-1))])])}const R=p(k,[["render",u]]);export{m as __pageData,R as default};
